jest.mock('../src/middleware/errorHandler', () => ({
  asyncHandler: (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next),
}))

jest.mock('../src/services/adminWhitelistService', () => ({
  verifyAdminCredentials: jest.fn(),
  normalizeUsername: (value) => (value || '').toString().trim().toLowerCase(),
}))

jest.mock('../src/services/adminAnalyticsService', () => ({
  getSummary: jest.fn(),
  getAnonymousAcquisitionSummary: jest.fn(),
  getAnonymousAcquisitionCampaigns: jest.fn(),
  getAnonymousAcquisitionRecent: jest.fn(),
  getAnonymousAcquisitionDiagnostics: jest.fn(),
  sendAnonymousAcquisitionTestEvent: jest.fn(),
  getActivationFunnel: jest.fn(),
}))

jest.mock('../src/middleware/requireWritableNode', () => ({
  requireWritableNode: () => (_req, _res, next) => next(),
}))

const express = require('express')
const session = require('express-session')
const request = require('supertest')

const { verifyAdminCredentials } = require('../src/services/adminWhitelistService')
const adminAnalyticsService = require('../src/services/adminAnalyticsService')
const adminAuthRouter = require('../src/routes/adminAuth')
const adminAnalyticsRouter = require('../src/routes/adminAnalytics')

function makeApp() {
  const app = express()
  app.use(express.json({ limit: '32kb' }))
  app.use(
    session({
      secret: 'test_admin_session_secret',
      resave: false,
      saveUninitialized: false,
      cookie: { httpOnly: true, sameSite: 'lax' },
    }),
  )
  app.use('/api/admin/auth', adminAuthRouter)
  app.use('/api/admin/analytics', adminAnalyticsRouter)
  // eslint-disable-next-line no-unused-vars
  app.use((err, _req, res, _next) => res.status(err.statusCode || 500).json({ success: false, error: err.message }))
  return app
}

beforeEach(() => {
  verifyAdminCredentials.mockReset()
  for (const fn of Object.values(adminAnalyticsService)) {
    if (fn && typeof fn.mockReset === 'function') fn.mockReset()
  }
})

test('GET /api/admin/analytics/summary requires an admin session', async () => {
  const app = makeApp()

  const res = await request(app).get('/api/admin/analytics/summary?site=kubus.site')
  expect(res.status).toBe(401)
  expect(res.body).toEqual({ success: false, error: 'Admin authentication required' })
})

test('Admin login establishes a session for analytics endpoints', async () => {
  const app = makeApp()
  const agent = request.agent(app)

  verifyAdminCredentials.mockResolvedValue({ username: 'test_admin', roles: ['admin'] })
  adminAnalyticsService.getSummary.mockResolvedValue({ pageViews: 123, uniqueVisitors: 45 })

  const login = await agent.post('/api/admin/auth/login').send({ username: 'test_admin', password: 'pw' })
  expect(login.status).toBe(200)
  expect(login.body.success).toBe(true)
  expect(login.body.admin).toEqual({ username: 'test_admin', roles: ['admin'] })
  expect(typeof login.body.csrfToken).toBe('string')

  const res = await agent
    .get('/api/admin/analytics/summary')
    .query({ site: 'kubus.site', from: '2026-01-01T00:00:00.000Z', to: '2026-01-02T00:00:00.000Z', ingest: '/a' })

  expect(res.status).toBe(200)
  expect(res.body).toEqual({ success: true, data: { pageViews: 123, uniqueVisitors: 45 } })
  expect(adminAnalyticsService.getSummary).toHaveBeenCalledWith(
    expect.objectContaining({
      site: 'kubus.site',
      from: '2026-01-01T00:00:00.000Z',
      to: '2026-01-02T00:00:00.000Z',
      ingest: '/a',
    }),
  )
})

